static real_t sum_1d(real_t *arr, Index_type n) {
    real_t s = 0.0;
    for (Index_type i = 0; i < n; ++i) s += arr[i];
    return s;
}

static real_t sum_2d(real_t (*arr)[LEN_2D], Index_type m, Index_type n) {
    real_t s = 0.0;
    for (Index_type i = 0; i < m; ++i)
        for (Index_type j = 0; j < n; ++j) s += arr[i][j];
    return s;
}

static void fill_seq(real_t *arr, Index_type n, real_t base, real_t step) {
    for (Index_type i = 0; i < n; ++i) arr[i] = base + step * (real_t)i;
}

static void fill_const(real_t *arr, Index_type n, real_t v) {
    for (Index_type i = 0; i < n; ++i) arr[i] = v;
}

static void fill_neg_alt(real_t *arr, Index_type n, real_t v) {
    for (Index_type i = 0; i < n; ++i) arr[i] = ((i % 2) ? -v : v);
}

static void fill_2d_seq(real_t (*arr)[LEN_2D], Index_type m, Index_type n, real_t base) {
    for (Index_type i = 0; i < m; ++i)
        for (Index_type j = 0; j < n; ++j)
            arr[i][j] = base + 1e-3 * (real_t)(i * n + j);
}

int initialise_arrays(const char *name) {
    if (!strcmp(name, "lcals_diff_predict")) {
        fill_seq(cx, LEN_1D * 14, 1.0, 1e-7);
        fill_seq(px, LEN_1D * 14, 0.5, 1e-7);
    }
    else if (!strcmp(name, "lcals_eos")) {
        fill_seq(u, LEN_1D + 16, 1.0, 1e-7);
        fill_seq(y, LEN_1D, 2.0, 1e-7);
        fill_seq(z, LEN_1D, 3.0, 1e-7);
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "lcals_first_diff")) {
        fill_seq(y, LEN_1D, 0.0, 1e-3);
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "lcals_first_sum")) {
        fill_seq(y, LEN_1D, 1.0, 1e-3);
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "lcals_hydro_1d")) {
        fill_seq(y, LEN_1D, 1.0, 1e-7);
        fill_seq(z, LEN_1D, 2.0, 1e-7);
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "lcals_int_predict")) {
        fill_seq(px, LEN_1D * 14, 0.5, 1e-7);
    }
    else if (!strcmp(name, "lcals_planckian")) {
        fill_seq(u, LEN_1D + 16, 1.0, 1e-3);
        fill_seq(v, LEN_1D, 2.0, 1e-3);
        fill_seq(x, LEN_1D, 0.5, 1e-3);
    }
    else if (!strcmp(name, "lcals_tridiag_elim")) {
        fill_seq(xin, LEN_1D, 1.0, 1e-3);
        fill_seq(y,   LEN_1D, 2.0, 1e-3);
        fill_seq(z,   LEN_1D, 0.5, 1e-3);
    }
    else if (!strcmp(name, "lcals_gen_lin_recur")) {
        fill_seq(sa,   LEN_1D, 1.0e-6, 1e-9);
        fill_seq(sb,   LEN_1D, 1.0,    0.0);
        fill_seq(stb5, LEN_1D, 0.5,    0.0);
        fill_const(b5, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "lcals_hydro_2d")) {
        fill_2d_seq(zp, LEN_2D, LEN_2D, 1.0);
        fill_2d_seq(zq, LEN_2D, LEN_2D, 0.5);
        fill_2d_seq(zr, LEN_2D, LEN_2D, 0.25);
        fill_2d_seq(zm, LEN_2D, LEN_2D, 1.5);
        fill_2d_seq(zz, LEN_2D, LEN_2D, 2.0);
        fill_2d_seq(za, LEN_2D, LEN_2D, 0.0);
        fill_2d_seq(zb, LEN_2D, LEN_2D, 0.0);
        fill_2d_seq(zu, LEN_2D, LEN_2D, 0.1);
        fill_2d_seq(zv, LEN_2D, LEN_2D, 0.2);
        fill_2d_seq(zrout, LEN_2D, LEN_2D, 0.0);
        fill_2d_seq(zzout, LEN_2D, LEN_2D, 0.0);
    }
    else if (!strcmp(name, "stream_add")) {
        fill_seq(a, LEN_1D, 0.0, 1e-3);
        fill_seq(b, LEN_1D, 1.0, 1e-3);
        fill_seq(c, LEN_1D, 2.0, 1e-3);
    }
    else if (!strcmp(name, "stream_copy")) {
        fill_seq(a, LEN_1D, 0.0, 1e-3);
        fill_seq(b, LEN_1D, 1.0, 1e-3);
        fill_seq(c, LEN_1D, 2.0, 1e-3);
    }
    else if (!strcmp(name, "stream_mul")) {
        fill_seq(a, LEN_1D, 0.0, 1e-3);
        fill_seq(b, LEN_1D, 1.0, 1e-3);
        fill_seq(c, LEN_1D, 2.0, 1e-3);
    }
    else if (!strcmp(name, "stream_triad")) {
        fill_seq(a, LEN_1D, 0.0, 1e-3);
        fill_seq(b, LEN_1D, 1.0, 1e-3);
        fill_seq(c, LEN_1D, 2.0, 1e-3);
    }
    else if (!strcmp(name, "stream_dot")) {
        fill_seq(a, LEN_1D, 0.0, 1e-3);
        fill_seq(b, LEN_1D, 1.0, 1e-3);
        fill_seq(c, LEN_1D, 2.0, 1e-3);
    }
    else if (!strcmp(name, "lcals_first_min")) {
        fill_seq(x, LEN_1D, 1.0, 1e-3);
        x[LEN_1D / 2] = -1.0e+10;
        fill_const(y, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_daxpy")) {
        fill_seq(x, LEN_1D, 0.0, 1e-3);
        fill_const(y, LEN_1D, 1.0);
    }
    else if (!strcmp(name, "basic_if_quad")) {
        fill_seq(a,    LEN_1D, 1.0, 1e-3);
        fill_seq(b,    LEN_1D, 0.5, 1e-3);
        fill_seq(c,    LEN_1D, 0.25, 1e-3);
        fill_const(out1, LEN_1D, 0.0);
        fill_const(out2, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_init3")) {
        fill_seq(in1, LEN_1D, 1.0, 1e-3);
        fill_seq(in2, LEN_1D, 0.5, 1e-3);
    }
    else if (!strcmp(name, "basic_init_view1d")) {
        fill_const(a, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_init_view1d_offset")) {
        fill_const(a, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_muladdsub")) {
        fill_seq(in1, LEN_1D, 1.0, 1e-3);
        fill_seq(in2, LEN_1D, 0.5, 1e-3);
    }
    else if (!strcmp(name, "basic_nested_init")) {
        (void)0;
    }
    else if (!strcmp(name, "basic_pi_reduce")) {
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_trap_int")) {
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_reduce3_int")) {
        for (Index_type i = 0; i < LEN_1D; ++i) idx_list[i] = (Index_type)((i * 1103515245LL + 12345LL) & 0x7FFFFFFFLL);
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_reduce_struct")) {
        fill_seq(x, LEN_1D, 1.0, 1e-7);
        fill_seq(y, LEN_1D, 2.0, 1e-7);
        fill_const(z, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_copy8")) {
        for (Index_type i = 0; i < LEN_1D; ++i) { a[i] = (real_t)i; b[i] = (real_t)i + 1; c[i] = (real_t)i + 2; d[i] = (real_t)i + 3; e[i] = (real_t)i + 4; }
        fill_const(out1, LEN_1D, 0.0);
        fill_const(out2, LEN_1D, 0.0);
        fill_const(out3, LEN_1D, 0.0);
        fill_const(in1,  LEN_1D, 0.0);
        fill_const(in2,  LEN_1D, 0.0);
        fill_const(x,    LEN_1D, 0.0);
        fill_const(y,    LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_daxpy_atomic")) {
        fill_seq(x, LEN_1D, 0.0, 1e-3);
        fill_const(y, LEN_1D, 1.0);
    }
    else if (!strcmp(name, "basic_pi_atomic")) {
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "basic_indexlist")) {
        for (Index_type i = 0; i < LEN_1D; ++i) x[i] = ((i * 31) % 7 < 3) ? -1.0 : 1.0;
        for (Index_type i = 0; i < LEN_1D; ++i) idx_list[i] = 0;
    }
    else if (!strcmp(name, "basic_indexlist_3loop")) {
        for (Index_type i = 0; i < LEN_1D; ++i) x[i] = ((i * 31) % 7 < 3) ? -1.0 : 1.0;
        for (Index_type i = 0; i < LEN_1D + 1; ++i) idx_counts[i] = 0;
        for (Index_type i = 0; i < LEN_1D; ++i) idx_list[i] = 0;
    }
    else if (!strcmp(name, "algorithm_memcpy")) {
        fill_seq(x, LEN_1D, 1.0, 1e-3);
        fill_const(y, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "algorithm_memset")) {
        fill_const(x, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "algorithm_reduce_sum")) {
        fill_seq(x, LEN_1D, 1.0, 1e-7);
        fill_const(y, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "algorithm_scan")) {
        fill_seq(x, LEN_1D, 1.0, 1e-7);
        fill_const(y, LEN_1D, 0.0);
    }
    else if (!strcmp(name, "algorithm_histogram")) {
        for (Index_type i = 0; i < LEN_1D; ++i) idx_list[i] = (Index_type)((i * 2654435761u) & 0xFF);
        fill_const(x, 256, 0.0);
    }
    else {
        fprintf(stderr, "unknown kernel name: %s\n", name); exit(1);
    }
    return 0;
}

real_t calc_checksum(const char *name) {
    if (!strcmp(name, "lcals_diff_predict")) {
        return sum_1d(px, LEN_1D * 14);
    }
    else if (!strcmp(name, "lcals_eos")) {
        return sum_1d(x, LEN_1D - 6);
    }
    else if (!strcmp(name, "lcals_first_diff")) {
        return sum_1d(x, LEN_1D - 1);
    }
    else if (!strcmp(name, "lcals_first_sum")) {
        return sum_1d(x, LEN_1D);
    }
    else if (!strcmp(name, "lcals_hydro_1d")) {
        return sum_1d(x, LEN_1D - 12);
    }
    else if (!strcmp(name, "lcals_int_predict")) {
        return sum_1d(px, LEN_1D * 14);
    }
    else if (!strcmp(name, "lcals_planckian")) {
        return sum_1d(w, LEN_1D);
    }
    else if (!strcmp(name, "lcals_tridiag_elim")) {
        return sum_1d(xout, LEN_1D);
    }
    else if (!strcmp(name, "lcals_gen_lin_recur")) {
        return sum_1d(b5, LEN_1D) + sum_1d(stb5, LEN_1D);
    }
    else if (!strcmp(name, "lcals_hydro_2d")) {
        return sum_2d(zrout, LEN_2D, LEN_2D) + sum_2d(zzout, LEN_2D, LEN_2D);
    }
    else if (!strcmp(name, "stream_add")) {
        return sum_1d(c, LEN_1D);
    }
    else if (!strcmp(name, "stream_copy")) {
        return sum_1d(c, LEN_1D);
    }
    else if (!strcmp(name, "stream_mul")) {
        return sum_1d(b, LEN_1D);
    }
    else if (!strcmp(name, "stream_triad")) {
        return sum_1d(a, LEN_1D);
    }
    else if (!strcmp(name, "stream_dot")) {
        return x[0];
    }
    else if (!strcmp(name, "lcals_first_min")) {
        return y[0] + y[1];
    }
    else if (!strcmp(name, "basic_daxpy")) {
        return sum_1d(y, LEN_1D);
    }
    else if (!strcmp(name, "basic_if_quad")) {
        return sum_1d(out1, LEN_1D) + sum_1d(out2, LEN_1D);
    }
    else if (!strcmp(name, "basic_init3")) {
        return sum_1d(out1, LEN_1D);
    }
    else if (!strcmp(name, "basic_init_view1d")) {
        return sum_1d(a, LEN_1D);
    }
    else if (!strcmp(name, "basic_init_view1d_offset")) {
        return sum_1d(a, LEN_1D - 1);
    }
    else if (!strcmp(name, "basic_muladdsub")) {
        return sum_1d(out1, LEN_1D) + sum_1d(out2, LEN_1D) + sum_1d(out3, LEN_1D);
    }
    else if (!strcmp(name, "basic_nested_init")) {
        return sum_1d(array3d, LEN_2D * LEN_2D * 8);
    }
    else if (!strcmp(name, "basic_pi_reduce")) {
        return x[0];
    }
    else if (!strcmp(name, "basic_trap_int")) {
        return x[0];
    }
    else if (!strcmp(name, "basic_reduce3_int")) {
        return x[0] + x[1] + x[2];
    }
    else if (!strcmp(name, "basic_reduce_struct")) {
        return z[0] + z[1] + z[2] + z[3] + z[4] + z[5];
    }
    else if (!strcmp(name, "basic_copy8")) {
        return sum_1d(out1, LEN_1D) + sum_1d(out2, LEN_1D) + sum_1d(out3, LEN_1D) + sum_1d(in1, LEN_1D) + sum_1d(in2, LEN_1D) + sum_1d(x, LEN_1D) + sum_1d(y, LEN_1D);
    }
    else if (!strcmp(name, "basic_daxpy_atomic")) {
        return sum_1d(y, LEN_1D);
    }
    else if (!strcmp(name, "basic_pi_atomic")) {
        return x[0];
    }
    else if (!strcmp(name, "basic_indexlist")) {
        return (real_t)idx_list[0];
    }
    else if (!strcmp(name, "basic_indexlist_3loop")) {
        return (real_t)idx_list[0];
    }
    else if (!strcmp(name, "algorithm_memcpy")) {
        return sum_1d(y, LEN_1D);
    }
    else if (!strcmp(name, "algorithm_memset")) {
        return sum_1d(x, LEN_1D);
    }
    else if (!strcmp(name, "algorithm_reduce_sum")) {
        return y[0];
    }
    else if (!strcmp(name, "algorithm_scan")) {
        return sum_1d(y, LEN_1D);
    }
    else if (!strcmp(name, "algorithm_histogram")) {
        return sum_1d(x, 256);
    }
    else {
        fprintf(stderr, "unknown kernel name: %s\n", name); exit(1);
    }
}

