#include <stdio.h>
#include <stdlib.h>

#include "common.h"
#include "array_defs.h"

typedef real_t(*test_function_t)(struct args_t *);

real_t lcals_first_min(struct args_t *func_args);

void time_function(test_function_t vector_func, void *arg_info)
{
    struct args_t func_args = {.arg_info = arg_info};
    double result = vector_func(&func_args);
    double tic = func_args.t1.tv_sec + (func_args.t1.tv_usec / 1000000.0);
    double toc = func_args.t2.tv_sec + (func_args.t2.tv_usec / 1000000.0);
    double taken = toc - tic;
    printf("%10.3f\t%f\n", taken, result);
}

int main(void)
{
    printf("Loop \tTime(sec) \tChecksum\n");
    time_function(&lcals_first_min, NULL);
    return EXIT_SUCCESS;
}

