real_t basic_nested_init(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type nk = 8, nj = LEN_2D, ni = LEN_2D;
    for (int nl = 0; nl < iterations / 32 + 1; nl++) {
        for (Index_type k = 0; k < nk; ++k) {
            for (Index_type j = 0; j < nj; ++j) {
                for (Index_type i = 0; i < ni; ++i) {
                    array3d[i + ni*(j + nj*k)] = 0.00000001 * (real_t)i * (real_t)j * (real_t)k;
                }
            }
        }
        dummy(array3d, NULL, NULL, NULL, NULL, 0.0);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

