real_t basic_indexlist(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type len = 0;
    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
        Index_type count = 0;
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (x[i] < 0.0) {
                idx_list[count++] = i;
            }
        }
        len = count;
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)count);
    }
    idx_list[0] = len;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

