code:
real_t basic_indexlist_3loop(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type len = 0;
    for (int nl = 0; nl < iterations / 8 + 1; nl++) {
        for (Index_type i = 0; i < LEN_1D; ++i) {
            idx_counts[i] = (x[i] < 0.0) ? 1 : 0;
        }
        Index_type count = 0;
        for (Index_type i = 0; i <= LEN_1D; ++i) {
            Index_type inc = idx_counts[i];
            idx_counts[i] = count;
            count += inc;
        }
        for (Index_type i = 0; i < LEN_1D; ++i) {
            if (idx_counts[i] != idx_counts[i+1]) {
                idx_list[idx_counts[i]] = i;
            }
        }
        len = idx_counts[LEN_1D];
        dummy(NULL, NULL, NULL, NULL, NULL, (real_t)count);
    }
    idx_list[0] = len;

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

